package com.yesbee.nwtrack.workflow;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.yesbee.nwtrack.shared.BusinessRuleException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.*;

@Service
public class OperationsService {
    private final JdbcTemplate jdbc;private final ObjectMapper json;private final StationAccessService access;
    public OperationsService(JdbcTemplate jdbc,ObjectMapper json,StationAccessService access){this.jdbc=jdbc;this.json=json;this.access=access;}

    public Map<String,Object> resolveNfc(String uid){List<Map<String,Object>> rows=jdbc.queryForList("select n.id tag_id,n.uid,n.asset_type,n.active,n.trolley_id,t.code trolley_code,a.lot_id,l.lot_number,sty.style_number,l.status lot_status,n.station_id,st.code station_code,n.process_id,p.code process_code,n.machine_id,m.name machine_name,m.status machine_status,n.storage_area_id,sa.code storage_area_code,n.storage_location_id,sl.code storage_unit_code from nfc_tags n left join trolleys t on t.id=n.trolley_id left join lot_trolley_assignments a on a.trolley_id=t.id and a.released_at is null left join lots l on l.id=a.lot_id left join styles sty on sty.id=l.style_id left join stations st on st.id=n.station_id left join processes p on p.id=n.process_id left join machines m on m.id=n.machine_id left join storage_areas sa on sa.id=n.storage_area_id left join storage_locations sl on sl.id=n.storage_location_id where n.uid=?",uid.trim());if(rows.isEmpty())throw new BusinessRuleException("UNKNOWN_NFC","NFC tag is not registered");Map<String,Object> result=rows.getFirst();if(!Boolean.TRUE.equals(result.get("active")))throw new BusinessRuleException("NFC_RETIRED","NFC tag is inactive");return result;}

    @Transactional public void linkTrolley(UUID lotId,UUID trolleyId,UUID actor){String lotStatus=jdbc.queryForObject("select status from lots where id=? for update",String.class,lotId);if(Set.of("COMPLETED","CANCELLED","IN_STORAGE").contains(lotStatus))throw new BusinessRuleException("TROLLEY_LINK_NOT_ALLOWED","Lot cannot be linked in its current state");Integer occupied=jdbc.queryForObject("select count(*) from lot_trolley_assignments where trolley_id=? and released_at is null",Integer.class,trolleyId);if(occupied!=null&&occupied>0)throw new BusinessRuleException("TROLLEY_OCCUPIED","Trolley is already assigned");Integer assigned=jdbc.queryForObject("select count(*) from lot_trolley_assignments where lot_id=? and released_at is null",Integer.class,lotId);if(assigned!=null&&assigned>0)throw new BusinessRuleException("LOT_ALREADY_LINKED","Lot already has an active trolley");jdbc.update("insert into lot_trolley_assignments(id,lot_id,trolley_id,linked_by) values (?,?,?,?)",UUID.randomUUID(),lotId,trolleyId,actor);jdbc.update("update trolleys set status='IN_USE',version=version+1 where id=? and active",trolleyId);jdbc.update("update lots set current_location_type='TROLLEY',current_location_id=?,version=version+1 where id=?",trolleyId,lotId);location(lotId,"TROLLEY",trolleyId,actor);}

    @Transactional public Map<String,Object> dispatch(UUID lotId,UUID actor){LotRow lot=jdbc.queryForObject("select id,lot_number,status,current_route_sequence from lots where id=? for update",(rs,n)->new LotRow((UUID)rs.getObject(1),rs.getString(2),rs.getString(3),(Integer)rs.getObject(4)),lotId);if(lot==null)throw new BusinessRuleException("LOT_NOT_FOUND","Lot not found");Integer trolleyCount=jdbc.queryForObject("select count(*) from lot_trolley_assignments where lot_id=? and released_at is null",Integer.class,lotId);if(trolleyCount==null||trolleyCount==0)throw new BusinessRuleException("TROLLEY_REQUIRED","Link a trolley before Dispatch");int sequence=lot.currentSequence()==null?1:lot.currentSequence();if("READY_FOR_DISPATCH".equals(lot.status()))sequence++;Map<String,Object> visit=jdbc.queryForMap("select sv.id visit_id,sv.station_id,s.code station_code,st.style_number from station_visits sv join lot_route_entries lre on lre.id=sv.lot_route_entry_id join stations s on s.id=sv.station_id join lots l on l.id=sv.lot_id join styles st on st.id=l.style_id where sv.lot_id=? and lre.sequence_no=?",lotId,sequence);UUID visitId=(UUID)visit.get("visit_id"),stationId=(UUID)visit.get("station_id");jdbc.update("update station_visits set status='DISPATCHED',dispatched_at=now(),version=version+1 where id=?",visitId);jdbc.update("update lot_route_entries set status='DISPATCHED' where lot_id=? and sequence_no=?",lotId,sequence);jdbc.update("update lots set status='DISPATCHED',current_route_sequence=?,version=version+1 where id=?",sequence,lotId);Map<String,Object> payload=new LinkedHashMap<>();payload.put("lotId",lotId);payload.put("lotNumber",lot.lotNumber());payload.put("styleNumber",visit.get("style_number"));payload.put("destinationStationId",stationId);payload.put("destinationStation",visit.get("station_code"));payload.put("visitId",visitId);try{jdbc.update("insert into outbox_events(id,aggregate_type,aggregate_id,aggregate_version,event_type,payload) values (?,'LOT',?,1,'INCOMING_LOT',?::jsonb)",UUID.randomUUID(),lotId,json.writeValueAsString(payload));}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException(e);}return payload;}

    @Transactional public void retrieveStorage(UUID storageId,UUID lotId,UUID trolleyId,UUID actor){UUID station=jdbc.queryForObject("select station_id from storage_locations where id=?",UUID.class,storageId);access.assertCanOperate(actor,station);List<Map<String,Object>> rows=jdbc.queryForList("select id,lot_id from storage_occupancies where storage_location_id=? and lot_id=? and retrieved_at is null for update",storageId,lotId);if(rows.isEmpty())throw new BusinessRuleException("STORAGE_OCCUPANCY_NOT_FOUND","Selected Lot is not actively stored in this Storage Unit");Integer occupied=jdbc.queryForObject("select count(*) from lot_trolley_assignments where trolley_id=? and released_at is null",Integer.class,trolleyId);if(occupied!=null&&occupied>0)throw new BusinessRuleException("TROLLEY_OCCUPIED","Trolley is already assigned");UUID occupancyId=(UUID)rows.getFirst().get("id");jdbc.update("update storage_occupancies set retrieved_at=now(),retrieved_by=? where id=?",actor,occupancyId);jdbc.update("insert into lot_trolley_assignments(id,lot_id,trolley_id,linked_by) values (?,?,?,?)",UUID.randomUUID(),lotId,trolleyId,actor);jdbc.update("update trolleys set status='IN_USE',version=version+1 where id=? and active",trolleyId);jdbc.update("update lots set status='AT_STATION',current_location_type='TROLLEY',current_location_id=?,version=version+1 where id=?",trolleyId,lotId);location(lotId,"TROLLEY",trolleyId,actor);}

    @Transactional public String transition(UUID executionId,String target,String reason,UUID actor,boolean supervisor){ExecRow row=jdbc.queryForObject("select pe.status,pe.station_visit_id,pe.sequence_no,sv.station_id from process_executions pe join station_visits sv on sv.id=pe.station_visit_id where pe.id=? for update",(rs,n)->new ExecRow(rs.getString(1),(UUID)rs.getObject(2),rs.getInt(3),(UUID)rs.getObject(4)),executionId);if(row==null)throw new BusinessRuleException("PROCESS_NOT_FOUND","Process execution not found");if(!supervisor)access.assertCanOperate(actor,row.stationId());if(!allowed(row.status(),target,supervisor))throw new BusinessRuleException("PROCESS_TRANSITION_INVALID","Cannot change Process from "+row.status()+" to "+target);if("IN_PROGRESS".equals(target)){Integer previous=jdbc.queryForObject("select count(*) from process_executions where station_visit_id=? and sequence_no<? and status not in ('COMPLETED','SKIPPED')",Integer.class,row.visitId(),row.sequence());if(previous!=null&&previous>0)throw new BusinessRuleException("PROCESS_ORDER_VIOLATION","Previous Processes must be resolved first");}jdbc.update("update process_executions set status=?,started_at=case when ?='IN_PROGRESS' and started_at is null then now() else started_at end,completed_at=case when ? in ('COMPLETED','SKIPPED') then now() else null end,operator_id=?,reason=?,version=version+1 where id=?",target,target,target,actor,reason,executionId);jdbc.update("insert into process_state_events(process_execution_id,from_status,to_status,actor_id,reason) values (?,?,?,?,?)",executionId,row.status(),target,actor,reason);if("IN_PROGRESS".equals(target))jdbc.update("update lots set status='IN_PROCESS',version=version+1 where id=(select lot_id from station_visits where id=?)",row.visitId());Integer remaining=jdbc.queryForObject("select count(*) from process_executions where station_visit_id=? and status not in ('COMPLETED','SKIPPED')",Integer.class,row.visitId());if(remaining!=null&&remaining==0){jdbc.update("update station_visits set status='READY_FOR_DISPATCH',version=version+1 where id=?",row.visitId());jdbc.update("update lots set status='READY_FOR_DISPATCH',version=version+1 where id=(select lot_id from station_visits where id=?)",row.visitId());}return target;}
    private boolean allowed(String from,String to,boolean supervisor){if(supervisor)return Set.of("PENDING","IN_PROGRESS","PAUSED","BLOCKED","SKIPPED","COMPLETED").contains(to);return switch(from){case"PENDING"->Set.of("IN_PROGRESS","SKIPPED").contains(to);case"IN_PROGRESS"->Set.of("PAUSED","BLOCKED","COMPLETED").contains(to);case"PAUSED"->"IN_PROGRESS".equals(to);case"BLOCKED"->Set.of("PENDING","IN_PROGRESS").contains(to);default->false;};}
    private void location(UUID lot,String type,UUID id,UUID actor){jdbc.update("insert into lot_location_events(lot_id,location_type,location_id,actor_id) values (?,?,?,?)",lot,type,id,actor);}
    private record LotRow(UUID id,String lotNumber,String status,Integer currentSequence){} private record ExecRow(String status,UUID visitId,int sequence,UUID stationId){}
}
